insert into public.events (
  id, event_name, event_url, normalized_event_url, dates, start_date, end_date,
  location, venue, cost, description, industry_vertical, exhibitor_mix, audience_mix,
  source, overall_score, reasoning, sales_brief, raw_data
) values (
  'fc21a7b8-f2a2-599c-adf1-dd08f2bf138c',
  'Broker Carrier Summit 2026',
  'https://brokercarriersummit.com/',
  'brokercarriersummit.com',
  'April 27-28, 2026',
  '2026-04-27',
  '2026-04-28',
  'Overland Park, KS',
  'Overland Park Convention Center',
  '$900-$2,500 per attendee',
  'A premier networking and professional development conference that brings together freight brokers and trucking carriers to build meaningful partnerships, featuring educational sessions, panel discussions, and workshops focused on fostering trust and collaboration in the freight and logistics industry.',
  'supply_chain_and_distribution',
  'Technology vendors and service providers including transportation management systems (TMS), factoring companies, freight validation services, load boards, logistics software platforms, carrier verification systems, freight technology startups, and freight fraud prevention solutions. Sponsors integrate into sessions rather than static exhibit booths.',
  'Freight brokers, trucking carriers (especially small to medium-sized operations), third-party logistics providers (3PLs), logistics professionals, fleet owners, and transportation technology decision-makers seeking to build reliable partnerships and industry relationships.',
  'enriched',
  3.1,
  'Broker Carrier Summit 2026 is fundamentally misaligned with InstaLILY ICP on multiple dimensions. The event serves freight brokers and trucking carriers - a pure logistics/transportation vertical focused on shipment coordination and carrier relationships. InstaLILY targets distributors, manufacturers, and field-service organizations with complex inventory management, parts catalogs, and multi-branch sales execution. The buyer personas (logistics coordinators, fleet operators, carrier managers) lack the operational and sales execution challenges that InstaLILY solves (quoting workflows, parts validation, order entry automation, tribal knowledge codification). While some 3PL attendees represent adjacent verticals, the event concentration is wrong. The technology vendors exhibiting (TMS platforms, load boards, factoring services, fraud prevention) target logistics optimization, not the revenue-driving execution workflows InstaLILY addresses. Investment in this event would yield poor lead quality and mismatched conversations.',
  'Low priority - wrong supply chain vertical. Broker-carrier summits serve freight logistics operators (3PLs, trucking), not distributors or manufacturers in InstaLILY ICP. Attendee focus on shipment coordination and carrier relationships, not parts management or sales execution. Technology vendor mix targets TMS and logistics optimization, not operational AI for distribution/manufacturing. Skip this event; focus resources on vertical distribution conferences (construction supply, industrial parts, food, automotive, healthcare) where buyer personas and pain points directly align with InstaLILY use cases.',
  '{"event_name":"Broker Carrier Summit 2026","event_url":"https://brokercarriersummit.com/","source":"enriched","needs_enrichment":true,"dates":"April 27-28, 2026","location":"Overland Park, KS","cost":"$900-$2,500 per attendee","venue":"Overland Park Convention Center","description":"A premier networking and professional development conference that brings together freight brokers and trucking carriers to build meaningful partnerships, featuring educational sessions, panel discussions, and workshops focused on fostering trust and collaboration in the freight and logistics industry.","industry_vertical":"supply_chain_and_distribution","exhibitor_mix":"Technology vendors and service providers including transportation management systems (TMS), factoring companies, freight validation services, load boards, logistics software platforms, carrier verification systems, freight technology startups, and freight fraud prevention solutions. Sponsors integrate into sessions rather than static exhibit booths.","audience_mix":"Freight brokers, trucking carriers (especially small to medium-sized operations), third-party logistics providers (3PLs), logistics professionals, fleet owners, and transportation technology decision-makers seeking to build reliable partnerships and industry relationships.","enriched":true,"enrichment_success":true,"enrichment_notes":"Event dates confirmed as April 27-28, 2026 in Kansas City metro area (Overland Park, KS). Cost range based on typical broker-carrier summit pricing. The event is held semiannually with another event scheduled for Dallas, TX in October 2026. Known as ''The Best 3 Days in Freight'' despite being a 2-day conference.","original_event_name":"Broker Carrier Summit 2026","original_event_url":"https://brokercarriersummit.com/","added_to_master":"2026-04-27T17:42:58.362682","master_id":48,"overall_score":3.1,"scores":{"supply_chain_vertical_alignment":{"score":2,"rationale":"Broker-carrier summit focuses on freight brokerage and trucking carrier operations - asset-light 3PLs and logistics service providers. This vertical is fundamentally misaligned with InstaLILY ICP. InstaLILY targets distributors, manufacturers, and field-service operations that manage complex inventory, parts catalogs, and multi-branch sales operations. Freight brokerage is a pure logistics/transportation play with no product distribution, parts management, or field-service execution components. Wrong supply chain vertical entirely."},"buyer_functional_alignment":{"score":5,"rationale":"Attendees are freight brokers, trucking carriers, 3PLs, and transportation logistics professionals. While some attendees hold operational roles, the dominant functions are logistics coordination, carrier relationship management, and load optimization - not sales operations, order management, or parts fulfillment that InstaLILY targets. Some supporting functions tangentially related to operations exist, but core buyer personas lack alignment with InstaLILY use cases."},"event_scale_timing":{"score":7,"rationale":"Well-established semiannual event with April 2026 dates falling squarely within target window. US-based in Kansas City metro (Overland Park, KS) making it geographically accessible to sales team. Moderate attendance event with strong industry reputation (though branded as 3 days despite being 2-day format). Represents meaningful industry gathering, though smaller than mega-conferences."},"buyer_seniority":{"score":3,"rationale":"Attendee base skews toward operational practitioners - fleet owners, logistics coordinators, and carrier partnership managers - rather than C-suite decision-makers. Technology decision-makers present but likely focused on TMS and carrier verification tools rather than broader operational AI. Limited evidence of VP/C-level concentration typical of enterprise software buying committees. Attendee profile suggests transaction-oriented rather than strategic purchasing authority."}},"reasoning":"Broker Carrier Summit 2026 is fundamentally misaligned with InstaLILY ICP on multiple dimensions. The event serves freight brokers and trucking carriers - a pure logistics/transportation vertical focused on shipment coordination and carrier relationships. InstaLILY targets distributors, manufacturers, and field-service organizations with complex inventory management, parts catalogs, and multi-branch sales execution. The buyer personas (logistics coordinators, fleet operators, carrier managers) lack the operational and sales execution challenges that InstaLILY solves (quoting workflows, parts validation, order entry automation, tribal knowledge codification). While some 3PL attendees represent adjacent verticals, the event concentration is wrong. The technology vendors exhibiting (TMS platforms, load boards, factoring services, fraud prevention) target logistics optimization, not the revenue-driving execution workflows InstaLILY addresses. Investment in this event would yield poor lead quality and mismatched conversations.","sales_brief":"Low priority - wrong supply chain vertical. Broker-carrier summits serve freight logistics operators (3PLs, trucking), not distributors or manufacturers in InstaLILY ICP. Attendee focus on shipment coordination and carrier relationships, not parts management or sales execution. Technology vendor mix targets TMS and logistics optimization, not operational AI for distribution/manufacturing. Skip this event; focus resources on vertical distribution conferences (construction supply, industrial parts, food, automotive, healthcare) where buyer personas and pain points directly align with InstaLILY use cases."}'::jsonb
) on conflict (id) do update set
  event_name = excluded.event_name, event_url = excluded.event_url,
  normalized_event_url = excluded.normalized_event_url, dates = excluded.dates,
  start_date = excluded.start_date, end_date = excluded.end_date,
  location = excluded.location, venue = excluded.venue, cost = excluded.cost,
  description = excluded.description, industry_vertical = excluded.industry_vertical,
  exhibitor_mix = excluded.exhibitor_mix, audience_mix = excluded.audience_mix,
  source = excluded.source, overall_score = excluded.overall_score,
  reasoning = excluded.reasoning, sales_brief = excluded.sales_brief,
  raw_data = excluded.raw_data;

