insert into public.events (
  id, event_name, event_url, normalized_event_url, dates, start_date, end_date,
  location, venue, cost, description, industry_vertical, exhibitor_mix, audience_mix,
  source, overall_score, reasoning, sales_brief, raw_data
) values (
  'c8c6dcd3-309c-5770-bfa7-199547c1a30f',
  'DELIVER Europe Amsterdam',
  'https://www.deliver.events/europe',
  'deliver.events/europe',
  'June 3-4, 2026',
  '2026-06-03',
  '2026-06-04',
  'Amsterdam, Netherlands',
  'TAETS Art and Event Park (Zaandam, Amsterdam)',
  'Fully hosted package for C and D-level executives (complimentary hotel accommodation, travel and meals, sponsored by attending vendors)',
  'The #1 matchmaking event for the retail and supply chain community in Europe, connecting over 1,000 C- and D-level retail executives with 140+ cutting-edge suppliers through precision matchmaking platform. Features expert-led conference sessions on retail, e-commerce, logistics, and supply chain innovation with a focus on sustainability and digital transformation.',
  'supply_chain_and_distribution',
  'E-commerce and logistics solution providers, last-mile delivery companies, warehouse automation vendors, supply chain technology providers, fulfillment service providers, carrier and shipping companies, returns management solutions, and retail technology vendors',
  'C- and D-level retail executives, e-commerce operations leaders, supply chain directors, logistics specialists, fulfillment managers, and logistics decision-makers from retail, e-commerce, and supply chain sectors. Expected 1,500 attendees including approximately 1,000 senior retail decision-makers.',
  'enriched',
  3.8,
  'Despite outstanding buyer seniority and functional alignment, this event is a poor fit for InstaLILY due to fundamental vertical misalignment and geographic accessibility issues. The audience is 80% retail and e-commerce operations leaders focused on last-mile delivery, fulfillment, and warehouse automation. InstaLILY solves execution problems for B2B distributors, manufacturers, and field service - not retail fulfillment. International location in Netherlands makes US sales team participation impractical.',
  'Lower Priority - Wrong vertical mix. DELIVER Europe brings excellent decision-maker quality and seniority, but audience is retail/e-commerce fulfillment focused, not B2B distributors or manufacturers. Amsterdam location impractical for US team. Skip this event and prioritize North American distributor conferences instead.',
  '{"event_name":"DELIVER Europe Amsterdam","event_url":"https://www.deliver.events/europe","source":"enriched","needs_enrichment":true,"dates":"June 3-4, 2026","location":"Amsterdam, Netherlands","cost":"Fully hosted package for C and D-level executives (complimentary hotel accommodation, travel and meals, sponsored by attending vendors)","venue":"TAETS Art and Event Park (Zaandam, Amsterdam)","description":"The #1 matchmaking event for the retail and supply chain community in Europe, connecting over 1,000 C- and D-level retail executives with 140+ cutting-edge suppliers through precision matchmaking platform. Features expert-led conference sessions on retail, e-commerce, logistics, and supply chain innovation with a focus on sustainability and digital transformation.","industry_vertical":"supply_chain_and_distribution","exhibitor_mix":"E-commerce and logistics solution providers, last-mile delivery companies, warehouse automation vendors, supply chain technology providers, fulfillment service providers, carrier and shipping companies, returns management solutions, and retail technology vendors","audience_mix":"C- and D-level retail executives, e-commerce operations leaders, supply chain directors, logistics specialists, fulfillment managers, and logistics decision-makers from retail, e-commerce, and supply chain sectors. Expected 1,500 attendees including approximately 1,000 senior retail decision-makers.","enriched":true,"enrichment_success":true,"enrichment_notes":"Event is fully hosted for qualified C/D-level retail executives with VIP pass including accommodation and travel. Features precision matchmaking for pre-arranged meetings, conference sessions, and networking. 100% carbon-neutral and profit-neutral event (mission-led company). Conference topics include omnichannel fulfillment, AI in logistics, sustainable supply chains, and last-mile delivery.","original_event_name":"DELIVER Europe Amsterdam","original_event_url":"https://www.deliver.events/europe","added_to_master":"2026-04-30T12:08:52.587045","master_id":52,"overall_score":3.8,"scores":{"supply_chain_vertical_alignment":{"score":5,"rationale":"Event targets retail and e-commerce supply chain leaders with focus on last-mile delivery, fulfillment, and returns management. While this includes some logistics technology and warehouse automation vendors, the overwhelming attendee concentration is retail and e-commerce operations. This vertical misalignment is significant - InstaLILY target distributors, manufacturers, and field service in construction, industrial, healthcare, automotive, and food. Retail fulfillment operations are outside core ICP."},"buyer_functional_alignment":{"score":9,"rationale":"Excellent functional alignment with retail executives, e-commerce operations leaders, supply chain directors, and logistics decision-makers. C and D-level focus ensures high-intent, budget-holding attendees. These are exactly the operational and supply chain executive roles that drive buying decisions."},"event_scale_timing":{"score":2,"rationale":"Event is in 2026 which passes date check, but location is Amsterdam, Netherlands. US sales team accessibility is problematic for European event. While attendance scale is impressive (1,500 attendees), geographic location and associated travel costs make this a poor investment for US-centric sales strategy."},"buyer_seniority":{"score":9,"rationale":"Exceptional concentration of C and D-level retail executives with high budgetary authority. Event model provides fully hosted VIP experience for qualified decision-makers, indicating serious, intent-driven participation. 1,000+ senior retail decision-makers represent highest-level buyer concentration. Strong purchase authority and solution-seeking mentality evident from format."}},"reasoning":"Despite outstanding buyer seniority and functional alignment, this event is a poor fit for InstaLILY due to fundamental vertical misalignment and geographic accessibility issues. The audience is 80% retail and e-commerce operations leaders focused on last-mile delivery, fulfillment, and warehouse automation. InstaLILY solves execution problems for B2B distributors, manufacturers, and field service - not retail fulfillment. International location in Netherlands makes US sales team participation impractical.","sales_brief":"Lower Priority - Wrong vertical mix. DELIVER Europe brings excellent decision-maker quality and seniority, but audience is retail/e-commerce fulfillment focused, not B2B distributors or manufacturers. Amsterdam location impractical for US team. Skip this event and prioritize North American distributor conferences instead."}'::jsonb
) on conflict (id) do update set
