) values (
  '64d5a331-4f82-5525-a379-cfd92d069a38',
  'Multimodal Birmingham',
  'https://www.multimodal.org.uk/',
  'multimodal.org.uk',
  'June 30 - July 2, 2026',
  '2026-06-30',
  '2026-07-02',
  'Birmingham, UK',
  'NEC Birmingham',
  'Free to attend',
  'The UK and Ireland''s premier freight transport, logistics and supply chain management event, now in its 19th year. Features 300+ exhibitors showcasing solutions across road, rail, sea, air and warehousing, with 80+ free conference sessions covering decarbonisation, AI, supply chain resilience, and the future of trade. Co-located with Warehouse and Yard exhibitions, forming UK Logistics Week.',
  'supply_chain_and_distribution',
  'Freight forwarders, carriers, logistics service providers, warehouse automation vendors, technology providers, rail freight companies, shipping and maritime companies, air cargo providers, supply chain software vendors, and materials handling equipment suppliers. 300+ exhibitors across all logistics modes.',
  'Shippers, retailers, manufacturers, logistics providers, freight forwarders, warehouse operators, supply chain professionals, cargo owners, and decision-makers across the entire UK logistics chain. Over 13,500 industry professionals attend.',
  'enriched',
  4.6,
  'Multimodal is a major, established event with strong scale and free attendance that attracts legitimate supply chain decision-makers. However, it suffers from significant vertical misalignment - audience skews heavily toward logistics operators, freight forwarders, carriers, and 3PLs rather than InstaLILY target distributors and manufacturers. Geographic location in Birmingham, UK reduces US team accessibility versus domestic events. While some shippers and manufacturers attend, the event is infrastructure and modal-transport focused rather than execution-focused operational workflows that InstaLILY solves.',
  'Moderate priority - Large, established UK event with 13,500 attendees and strong operations/supply chain focus. However, vertical mix heavily weighted toward 3PLs, carriers, and freight forwarders rather than product distributors and manufacturers. UK location requires international travel. Consider only if sales team has existing European presence. Prioritize major North American distributor and manufacturing events over this logistics infrastructure event.',
  '{"event_name":"Multimodal Birmingham","event_url":"https://www.multimodal.org.uk/","source":"enriched","needs_enrichment":true,"dates":"June 30 - July 2, 2026","location":"Birmingham, UK","cost":"Free to attend","venue":"NEC Birmingham","description":"The UK and Ireland''s premier freight transport, logistics and supply chain management event, now in its 19th year. Features 300+ exhibitors showcasing solutions across road, rail, sea, air and warehousing, with 80+ free conference sessions covering decarbonisation, AI, supply chain resilience, and the future of trade. Co-located with Warehouse and Yard exhibitions, forming UK Logistics Week.","industry_vertical":"supply_chain_and_distribution","exhibitor_mix":"Freight forwarders, carriers, logistics service providers, warehouse automation vendors, technology providers, rail freight companies, shipping and maritime companies, air cargo providers, supply chain software vendors, and materials handling equipment suppliers. 300+ exhibitors across all logistics modes.","audience_mix":"Shippers, retailers, manufacturers, logistics providers, freight forwarders, warehouse operators, supply chain professionals, cargo owners, and decision-makers across the entire UK logistics chain. Over 13,500 industry professionals attend.","enriched":true,"enrichment_success":true,"enrichment_notes":"Free-to-attend event forming part of UK Logistics Week. Co-located with Warehouse (formerly IWLEX) and Yard (formerly YARDX) exhibitions, plus eDX (delivery and fulfilment). Features four conference theatres with presentations from Logistics UK, BIFA, UKWA, RFG, CILT and others. Conference sessions are CPD accredited. Multimodal Awards ceremony held evening of June 30. Free shuttle buses connect to Road Transport Expo (RTX) at Stoneleigh Park. Over 70 expert speakers and 80+ free conference sessions across three days.","original_event_name":"Multimodal Birmingham","original_event_url":"https://www.multimodal.org.uk/","added_to_master":"2026-04-30T12:08:52.587055","master_id":56,"overall_score":4.6,"scores":{"supply_chain_vertical_alignment":{"score":6,"rationale":"Event serves freight, logistics, and supply chain management with 300+ exhibitors across modal transportation (road, rail, sea, air) and warehousing. Strong presence of carriers, logistics providers, warehouse automation, and technology vendors. However, audience is heavily weighted toward logistics operators, freight forwarders, and 3PLs rather than InstaLILY target verticals of product distributors, manufacturers, and field service. Logistics infrastructure focus rather than distribution operations focus."},"buyer_functional_alignment":{"score":8,"rationale":"Excellent functional mix of supply chain professionals, logistics decision-makers, warehouse operators, and cargo owners with operational authority. These are operations and logistics management roles central to InstaLILY buyer personas. Large volume of shippers and manufacturers attendees increases relevance. However, significant portion of audience are carriers and logistics service providers outside core ICP."},"event_scale_timing":{"score":7,"rationale":"Established major event (19th year) in 2026 with 13,500+ industry professionals attending. Free attendance removes barrier. Located in Birmingham, UK - while not US-based, it is UK which has reasonable accessibility for US sales team travel compared to continental Europe. June-July timing is appropriate for sales cycle. Large scale and established reputation indicate quality event, but UK location reduces accessibility versus US events."},"buyer_seniority":{"score":6,"rationale":"Mix of senior supply chain professionals, decision-makers, and operators attending. Event features expert speakers and 80+ CPD-accredited conference sessions, attracting serious participants. However, attendee mix is broad across skill levels from junior logistics staff to senior decision-makers. Not explicitly C-suite focused. Logistics operator concentration suggests mid-level to senior management rather than highest executive authority."}},"reasoning":"Multimodal is a major, established event with strong scale and free attendance that attracts legitimate supply chain decision-makers. However, it suffers from significant vertical misalignment - audience skews heavily toward logistics operators, freight forwarders, carriers, and 3PLs rather than InstaLILY target distributors and manufacturers. Geographic location in Birmingham, UK reduces US team accessibility versus domestic events. While some shippers and manufacturers attend, the event is infrastructure and modal-transport focused rather than execution-focused operational workflows that InstaLILY solves.","sales_brief":"Moderate priority - Large, established UK event with 13,500 attendees and strong operations/supply chain focus. However, vertical mix heavily weighted toward 3PLs, carriers, and freight forwarders rather than product distributors and manufacturers. UK location requires international travel. Consider only if sales team has existing European presence. Prioritize major North American distributor and manufacturing events over this logistics infrastructure event."}'::jsonb
) on conflict (id) do update set
  event_name = excluded.event_name, event_url = excluded.event_url,
  normalized_event_url = excluded.normalized_event_url, dates = excluded.dates,
