insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bc707e33-2d99-5c60-8192-2a8c94e069f8', 'buyer_functional_alignment', 9, null, 'Strong alignment with operations, sales, and C-suite executives from industrial distributors. Audience includes operations directors, sales teams, and account managers - core InstaLILY buyer personas managing complex MROP supply chains and high-volume SKU catalogs.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bc707e33-2d99-5c60-8192-2a8c94e069f8', 'event_scale_timing', 9, null, 'Established annual convention in April 2026 at major venue (Huntington Convention Center, Cleveland). US-based, easily accessible to InstaLILY sales team, and well-timed for Q2 sales cycles. Strong industry reputation and consistent attendance from target verticals.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bc707e33-2d99-5c60-8192-2a8c94e069f8', 'buyer_seniority', 8, null, 'Explicit mention of C-suite executives and operations directors attending. Industrial distributors are PE-acquisition targets with growth mandates. Mix of senior leadership with significant decision-making authority over operations and technology investments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5a88a2d6-234a-5dfe-af1e-644b36066617', 'supply_chain_vertical_alignment', 6, null, 'MODEX focuses on warehouse automation, robotics, and material handling - tangential to InstaLILY core ICP. Event serves 3PLs, logistics operators, and DC managers. While warehouse operations overlap with distribution pain points, event skews toward hardware/robotics rather than execution-focused AI for sales and operations workflows.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5a88a2d6-234a-5dfe-af1e-644b36066617', 'buyer_functional_alignment', 8, null, 'Operations-heavy audience with warehouse leaders, 3PL executives, supply chain directors, and operations VPs. Strong functional alignment to operations and logistics decision-makers. However, less sales-focused than ideal for InstaLILY''s quoting and sales acceleration use cases.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5a88a2d6-234a-5dfe-af1e-644b36066617', 'event_scale_timing', 8, null, 'Massive annual event - 50,000+ attendees, 1,000+ exhibitors at Georgia World Congress Center in April 2026. Major US event with strong accessibility and established reputation. Timing and scale excellent for lead discovery despite vertical skew.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5a88a2d6-234a-5dfe-af1e-644b36066617', 'buyer_seniority', 6, null, 'Mix of operations VPs and logistics directors with decision-making authority, but audience skews toward mid-to-senior management rather than C-suite. Less concentration of procurement and sales executives with budget for AI automation than ideal.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1cb526cf-135a-50b3-8523-5e4332b84020', 'supply_chain_vertical_alignment', 10, null, 'SHIFT Conference is explicitly designed for wholesale distributors across all product verticals - perfect ICP alignment. Presented by Modern Distribution Management and NAW, this event directly serves construction supply, industrial parts, automotive, HVAC, fastener, and healthcare distributors that form InstaLILY core target market.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1cb526cf-135a-50b3-8523-5e4332b84020', 'buyer_functional_alignment', 10, null, 'Exceptional alignment: Distribution CEOs, sales leaders, digital transformation officers, operations executives, and data analytics teams. Audience composition matches InstaLILY buyer personas with direct authority over sales automation and operations transformation investments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1cb526cf-135a-50b3-8523-5e4332b84020', 'event_scale_timing', 9, null, 'Major May 2026 conference in Denver dedicated to distribution innovation. Established event with proven track record of attracting senior distribution leadership. US-based and easily accessible. May timing ideal for mid-year budget decisions and transformation initiatives.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1cb526cf-135a-50b3-8523-5e4332b84020', 'buyer_seniority', 9, null, 'Explicit focus on C-suite (CEOs, sales leaders) and digital transformation officers - the exact decision-makers for InstaLILY implementations. High concentration of executives with strategic authority and transformation mandates, indicating active solution-seeking and budget availability.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bb38cee1-ed0d-57fa-9789-43aa875e27b0', 'buyer_functional_alignment', 2, null, 'Architects, interior designers, and design-tech professionals dominate. Specifiers and engineers are design-oriented rather than operations or sales-focused. No evidence of procurement or operations executives managing distribution operations. Functional misalignment with InstaLILY buyer personas.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bb38cee1-ed0d-57fa-9789-43aa875e27b0', 'event_scale_timing', 7, null, 'Large annual event in June 2026 at San Diego Convention Center with 600+ exhibitors. Established event with good US accessibility and timing within optimal 2026 window. Scale is appropriate but industry vertical misalignment reduces relevance.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bb38cee1-ed0d-57fa-9789-43aa875e27b0', 'buyer_seniority', 1, null, 'Architects and designers are individual contributors and project-level decision-makers, not strategic operations or sales executives. Low seniority for InstaLILY buying decisions. Building product manufacturers attending as exhibitors, but specifiers are not procurement or operations decision-makers.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cff28d79-a0b3-5355-a541-d45f28fbf06a', 'supply_chain_vertical_alignment', 9, null, 'HVACR distribution is a direct match for InstaLILY ICP. Distributors in this vertical operate multi-location networks with high-volume SKU catalogs, complex inventory management, and reliance on experienced warehouse/branch managers. Regional conference format reaches established distributors facing operational scaling challenges and tribal knowledge loss.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cff28d79-a0b3-5355-a541-d45f28fbf06a', 'buyer_functional_alignment', 10, null, 'Audience includes warehouse managers, branch managers, operations directors, and sales leaders - precisely the operational and sales execution functions InstaLILY targets. These attendees own workflows around quoting, parts validation, order entry, and inventory decisions that AI Teammates can automate.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cff28d79-a0b3-5355-a541-d45f28fbf06a', 'event_scale_timing', 8, null, 'Four regional conferences across major US markets (Columbus, DC, Florida, Charlotte) in Q1-Q3 2026 provide multiple accessible entry points for US sales team. Established HARDI franchise means consistent attendance and sponsorship infrastructure. Regional format allows targeted outreach before events.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cff28d79-a0b3-5355-a541-d45f28fbf06a', 'buyer_seniority', 8, null, 'Operations directors and branch managers are strong decision-makers with budget authority for operational technology. Mix includes supplier executives and sales leaders. Regional conferences typically attract senior operational staff with P&L responsibility rather than purely tactical attendees.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bc6a566e-13bb-5464-9c96-611c3408c21a', 'buyer_functional_alignment', 5, null, 'Modular builders, prefab strategists, general contractors, and developers in attendance. While operations-related, audience is project-focused rather than multi-location distribution operations. Limited evidence of sales and operations teams from large distributors managing ongoing inventory and quoting workflows.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bc6a566e-13bb-5464-9c96-611c3408c21a', 'event_scale_timing', 6, null, 'April 2026 event in Las Vegas with 2026 timing confirmation. Venue details listed as TBA which suggests emerging event with less established brand. Likely smaller than major construction events but accessible to US sales team.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('bc6a566e-13bb-5464-9c96-611c3408c21a', 'buyer_seniority', 4, null, 'Prefab strategists and general contractor leadership likely attend, but audience skews toward project implementation and development rather than enterprise operations strategy. Limited C-suite or operations executive concentration expected. Modular construction is specialized niche within broader construction.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('beb00b03-de29-5cc6-ba90-31b2a84bcf56', 'buyer_functional_alignment', 4, null, 'BIM leaders, facility owners, architects, engineers, and government-facing firms. Audience skews toward technical and policy-focused roles rather than sales and operations executives. Building materials suppliers may attend but as exhibitors, not primary decision-makers for operational automation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('beb00b03-de29-5cc6-ba90-31b2a84bcf56', 'event_scale_timing', 6, null, 'May 2026 event in Tysons Corner, VA within 2026 window. Venue listed as TBA, suggesting emerging event with less establishment. US-based but niche industry focus limits broad accessibility relevance.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('beb00b03-de29-5cc6-ba90-31b2a84bcf56', 'buyer_seniority', 3, null, 'BIM leaders and facility directors are mid-level technical specialists rather than C-suite operations or sales decision-makers. Government and compliance focus attracts policy and standards professionals, not strategic operations buyers. Limited senior executive attendance expected.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('be4fded5-7670-5092-8fef-24eb9fc8ee87', 'buyer_functional_alignment', 3, null, 'CFOs, controllers, accounting managers, and financial analysts dominate. Finance and accounting professionals have limited operational authority over sales execution and warehouse operations workflows. No sales or operations leadership representation evident.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('be4fded5-7670-5092-8fef-24eb9fc8ee87', 'event_scale_timing', 7, null, 'May-June 2026 event in Phoenix within optimal timing window. US-based and accessible, likely established annual conference. Timing supports budget planning and financial review cycles though unrelated to InstaLILY sales/ops focus.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('be4fded5-7670-5092-8fef-24eb9fc8ee87', 'buyer_seniority', 4, null, 'CFOs and controllers have C-suite or near-C-suite seniority for financial decisions. However, construction financial professionals are not strategic purchasers for operational AI and sales execution platforms. Budget authority exists but for accounting/ERP systems, not distribution operations AI.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('b127dd43-3563-5a20-aa12-5fe4eca4495e', 'buyer_functional_alignment', 6, null, 'Mixed audience with HR leaders, executives, and construction company owners attending. While some decision-makers are present, event positioning emphasizes leadership and career growth rather than operational technology adoption. Sales and operations functions are not primary focus compared to professional development and diversity initiatives.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('b127dd43-3563-5a20-aa12-5fe4eca4495e', 'event_scale_timing', 6, null, 'Established event in June 2026 with good US location (San Diego). Timing is acceptable but venue details marked as TBA creates uncertainty about scale. Regional construction conference rather than major national event, limiting total addressable attendee pool.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('b127dd43-3563-5a20-aa12-5fe4eca4495e', 'buyer_seniority', 6, null, 'Executives and company owners present, but event attracts mixed seniority levels focused on career growth and mentorship. Not specifically positioned as C-suite decision-maker gathering. Some senior stakeholders but not concentrated among operations or procurement leaders.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('0a1dc062-7a06-50ed-b684-b6633c1f5ac0', 'buyer_functional_alignment', 7, null, 'Audience includes general contractors, specialty contractors, builders, and developers alongside materials suppliers and equipment dealers. Operations and procurement functions present in attendee mix. Mix of buyer and vendor roles; some operational decision-makers but event serves broad construction ecosystem.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('0a1dc062-7a06-50ed-b684-b6633c1f5ac0', 'event_scale_timing', 6, null, 'Regional event in July 2026 with strong US location (Nashville). Positioned as focused on Middle Tennessee market expansion, suggesting moderate scale rather than major national conference. Free admission increases accessibility but may indicate smaller venue and lower executive concentration.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('0a1dc062-7a06-50ed-b684-b6633c1f5ac0', 'buyer_seniority', 6, null, 'Builders, contractors, and developers attend but seniority mix unclear from description. Event vendor mix suggests mid-market to smaller regional players. Limited evidence of C-suite concentration or procurement-focused decision-makers with budget authority for enterprise technology.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c985f3a3-e17b-5293-9544-79892d98b14e', 'buyer_functional_alignment', 3, null, 'Audience is engineers, manufacturers, process development professionals, and quality assurance managers focused on pharmaceutical manufacturing. Event emphasizes equipment, processing systems, and regulatory compliance. Minimal representation of sales, operations management, or procurement functions that drive InstaLILY adoption.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c985f3a3-e17b-5293-9544-79892d98b14e', 'event_scale_timing', 7, null, 'Major established event (500+ exhibitors) in April 2026 at prominent US location (New York, Javits Center). Strong event infrastructure and timing. Industry-only access ensures qualified attendees. Well-known pharma manufacturing event.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c985f3a3-e17b-5293-9544-79892d98b14e', 'buyer_seniority', 3, null, 'Process development professionals and quality managers dominate attendee base. C-level executives from pharma present but focused on manufacturing and development strategy. Limited evidence of operations, procurement, or supply chain decision-makers with budget authority for enterprise operational software.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8e6444d5-3712-59c0-825f-bffbeef3dc4e', 'supply_chain_vertical_alignment', 7, null, 'Procurement and supply chain leadership event. Procurement is rated 6-7 in criteria hierarchy but upper range applies here. Event broad-spectrum supply chain without deep specialization in asset-light 3PLs, freight forwarding, or LTL (highest tiers). Attendees span multiple supply chain segments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8e6444d5-3712-59c0-825f-bffbeef3dc4e', 'buyer_functional_alignment', 9, null, 'Senior procurement leaders, supply chain professionals, and sustainability champions. Event explicitly targets C/V/D level executives. Audience is procurement and supply chain operations-focused. Direct alignment with buyer functions that evaluate operational efficiency and digital transformation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8e6444d5-3712-59c0-825f-bffbeef3dc4e', 'event_scale_timing', 8, null, 'Major multi-track event in April 2026 (1,000+ attendees, 100+ speakers) at strong US location (Chicago, Navy Pier). Co-located with Sustainability LIVE adds adjacent audience. Rebranding as The US Summit in 2026 signals investment and expansion. Features awards ceremony indicating prestige.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8e6444d5-3712-59c0-825f-bffbeef3dc4e', 'buyer_seniority', 9, null, 'Event explicitly attracts C/V/D level executives from enterprise organizations. 2,000+ combined attendees (with Sustainability LIVE) but core procurement track focuses on senior buyer concentration. Focus on innovation and strategy indicates decision-maker participation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cd9e58f3-a35f-544e-ab84-377a303de7a8', 'supply_chain_vertical_alignment', 8, null, 'Supply management and procurement professional conference. Procurement rated as 6-7 in supply chain vertical hierarchy but ISM World shows strong institutional credibility and buyer concentration. Supply management spans multiple industries including distribution, manufacturing, and logistics.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cd9e58f3-a35f-544e-ab84-377a303de7a8', 'buyer_functional_alignment', 9, null, 'Supply chain professionals, procurement executives, category managers, sourcing directors, and supply management leaders. Event explicitly targets operations and procurement functions. Hands-on workshops and problem-solving labs indicate practical, workflow-focused attendees actively seeking solutions.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cd9e58f3-a35f-544e-ab84-377a303de7a8', 'event_scale_timing', 8, null, 'Major annual event (2,000+ attendees) in April 2026 at accessible US location (Denver/Aurora, 15 min from airport). 20-year institutional event by Institute for Supply Management signals credibility. Group discounts available. Hands-on workshop format and exec-track indicate investment in quality and specialization.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('cd9e58f3-a35f-544e-ab84-377a303de7a8', 'buyer_seniority', 9, null, '2,000 professionals from emerging to C-suite veterans. ExecIn2026 track specifically for VP+ attendees. Hands-on, problem-solving focus attracts senior decision-makers seeking practical solutions. Built by practitioners for practitioners indicates senior buyer participation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('12160569-8e0f-54b9-b30d-c3aa8cb62e3f', 'supply_chain_vertical_alignment', 7, null, 'Supply chain and logistics event with focus on 3PL/4PL partnerships, warehousing, distribution optimization, and supplier relationships. Strong warehousing and logistics alignment. Some 3PL/4PL content present. Broader logistics than highest-tier asset-light 3PL focus but still strong supply chain vertical.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('12160569-8e0f-54b9-b30d-c3aa8cb62e3f', 'buyer_functional_alignment', 9, null, 'Supply chain, logistics, procurement, and operations executives. Event explicitly targets VPs, directors, and senior managers in operations and supply chain. Focus on logistics strategy, warehousing optimization, and AI/automation indicates solution-seeking operational buyers.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('12160569-8e0f-54b9-b30d-c3aa8cb62e3f', 'event_scale_timing', 8, null, 'Established event in 10th year (April 2026, Dallas). 300+ senior-level attendees, 50+ speakers indicate solid scale for specialized event. Dallas location is strong US hub. Smaller than mega-conferences but higher quality buyer concentration expected in 300-person executive event.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('12160569-8e0f-54b9-b30d-c3aa8cb62e3f', 'buyer_seniority', 8, null, 'VPs, directors, and senior managers from manufacturing, retail, distribution, and logistics sectors. Leadership-focused platform emphasizes strategic discussions and executive case studies. 300-person scale with senior focus suggests high decision-maker concentration.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('b8bfa698-c53d-520a-87b9-35bd210b932b', 'buyer_functional_alignment', 0, null, 'Event is focused on marketing professionals, marketing operations, and demand generation - not sales operations or execution-focused roles. InstaLILY targets revenue operations, field sales, supply chain, and service delivery teams, not marketing departments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('b8bfa698-c53d-520a-87b9-35bd210b932b', 'event_scale_timing', 0, null, 'Specific 2026 dates not confirmed. Enrichment notes indicate URL is incomplete and 2026 dates could not be verified. Unable to confirm event is actually happening in 2026.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('b8bfa698-c53d-520a-87b9-35bd210b932b', 'buyer_seniority', 0, null, 'Event targets marketing managers and marketing operations professionals - typically lower seniority decision-makers without budget authority for operational AI platforms.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('e774e8e9-23ac-599a-82f7-8deb05a8dbc1', 'buyer_functional_alignment', 8, null, 'Strong alignment with distribution vertical. Audience includes food distributors (wholesale distributors, regional distributors, importers, brokers) managing product discovery, inventory, and buyer relationships. Food service distributors and foodservice professionals are explicit InstaLILY ICP. Sales operations and distribution management heavily represented.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('e774e8e9-23ac-599a-82f7-8deb05a8dbc1', 'event_scale_timing', 7, null, 'Large established event (June 28-30, 2026, New York). 47,000 attendees with 2,500 brands exhibiting - massive scale. Jacob K. Javits Convention Center accessible venue. June timing moderate but event is 70 years established. Confirmed dates.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('e774e8e9-23ac-599a-82f7-8deb05a8dbc1', 'buyer_seniority', 5, null, 'Audience includes retail buyers, e-commerce buyers, restaurateurs, and foodservice distributors - mix of mid-level and senior buying roles. While decision-makers present, event skews toward procurement and product discovery rather than C-suite operations/sales leadership focused on workflow automation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('389f07c8-1857-5d57-a4e0-db6c5cf03edf', 'buyer_functional_alignment', 7, null, 'Good alignment with operations and supply chain functions. Audience includes production managers, quality control directors, packaging managers, and distribution managers. These operational and supply chain leadership roles are relevant to InstaLILY, particularly for high-complexity inventory, multi-location operations, and supply chain workflows.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('389f07c8-1857-5d57-a4e0-db6c5cf03edf', 'event_scale_timing', 7, null, 'Established industry event (April 20-22, 2026, Philadelphia). Largest brewing industry gathering in North America. Pennsylvania Convention Center is accessible venue. April timing favorable for spring planning and investment cycles. Confirmed dates. Reputable Brewers Association event.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('389f07c8-1857-5d57-a4e0-db6c5cf03edf', 'buyer_seniority', 5, null, 'Audience includes brewery owners and production/operations managers - mix of owner/operator seniority alongside operational directors. While decision-making authority present, event skews more toward technical brewing operations and equipment rather than C-suite operations or sales leadership focused on workflow automation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fdc8238f-8965-5f0d-9981-3b68ff7240a0', 'buyer_functional_alignment', 7, null, 'Good alignment with food processing operations. Audience includes production managers, plant managers, operations directors, and quality assurance leaders. Operations and plant-level decision-makers are relevant to InstaLILY. However, event focus is food processing equipment and facility operations rather than distribution, sales operations, or field service.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fdc8238f-8965-5f0d-9981-3b68ff7240a0', 'event_scale_timing', 7, null, 'Largest regional food processing show on West Coast (April 19-20, 2026, Portland). 90,000 square feet of exhibit space indicates substantial scale. Free attendance is positive for attendee pull. April timing favorable for spring planning cycles. Oregon Convention Center is accessible venue. Confirmed dates.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fdc8238f-8965-5f0d-9981-3b68ff7240a0', 'buyer_seniority', 5, null, 'Audience is plant managers, production managers, operations directors, quality assurance leaders - strong operations seniority at plant level. However, attendees are focused on processing facility optimization and equipment rather than broader organizational workflow automation or sales operations decisions.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('35ac7666-7e08-56ed-a259-b227977024a7', 'industry_alignment', 7, null, 'Food supply vertical aligns with InstaLILY ICP, though dairy processing is more manufacturing-focused than distribution-focused. Dairy ingredient buyers and supply chain executives present represent operational decision-makers, but this is not a primary distribution vertical like Parts Town or SRS Distribution.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('35ac7666-7e08-56ed-a259-b227977024a7', 'scale_timing', 6, null, 'Established annual event in April 2026, US-based and accessible. Mid-sized conference focused on industry connectives. Timing is acceptable but not optimal for enterprise sales engagement. Regional reach is strong but not as broad as major national distribution conferences.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('35ac7666-7e08-56ed-a259-b227977024a7', 'buyer_quality', 6, null, 'Mix of operations managers, quality directors, and supply chain executives attending. Some C-suite presence but largely mid-to-senior operational staff. Decision-makers present but concentration of budget authority and strategic technology buyers is moderate rather than high.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('a627f5c2-532d-5be5-95d8-25167fb8a602', 'industry_alignment', 6, null, 'Pet food distribution is tangential food supply vertical. Distributors, manufacturers, and processors attend, but this is specialized niche market. Less relevant than broader food distribution or restaurant supply chain events. Limited overlap with InstaLILY core ICP of large multi-location distribution enterprises.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('a627f5c2-532d-5be5-95d8-25167fb8a602', 'scale_timing', 6, null, 'Focused industry event in April 2026, US-based location, dedicated single-industry focus. Event scale is moderate; establishes credibility but not major national conference scale. Timing is reasonable but not strategically optimal for broader enterprise sales engagement.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('a627f5c2-532d-5be5-95d8-25167fb8a602', 'buyer_quality', 6, null, 'Pet food distributors, manufacturers, and supply chain professionals attending. Some sales and operations decision-makers present, but this is niche vertical with fewer large enterprises and multi-location operations than broader food distribution. Seniority mix includes operations managers but C-suite concentration likely lower.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('567b9b99-3585-5d50-88d3-f8304fe18644', 'industry_alignment', 7, null, 'Food supply and distribution vertical aligns with InstaLILY ICP. Agri-food distributors, retail buyers, foodservice operators, and supply chain executives represent relevant buyer functions. However, event is located in Canada (Montreal), outside primary US geographic focus.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('567b9b99-3585-5d50-88d3-f8304fe18644', 'scale_timing', 6, null, 'Established major event with two decades of history. Late April/early May 2026 timing is acceptable. However, Canadian location outside US territory reduces accessibility for primary sales team.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('567b9b99-3585-5d50-88d3-f8304fe18644', 'buyer_quality', 7, null, 'Food distributors, retail buyers, supply chain executives, and procurement managers attending represent mix of operational and strategic decision-makers. Seniority and budget authority present but Canadian focus limits overlap with InstaLILY primary US enterprise customer base.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('069557b4-5da7-5abb-bac5-bada48be429b', 'industry_alignment', 6, null, 'Food safety and supply chain integrity focus serves food distributors and manufacturers, but event emphasis is regulatory compliance and contamination control rather than operational efficiency or sales execution. Attendees are food safety directors and quality assurance managers—functional alignment is weak compared to operations and sales leadership roles.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('069557b4-5da7-5abb-bac5-bada48be429b', 'scale_timing', 6, null, 'Major North American event in May 2026, US-based (Rosemont, IL). Scale and timing are strong. Accessibility is high for US sales team. However, conference focus on food safety solutions rather than AI-driven operational automation limits relevance to InstaLILY value proposition.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('069557b4-5da7-5abb-bac5-bada48be429b', 'buyer_quality', 3, null, 'Attendees are primarily food safety directors, quality assurance managers, and regulatory compliance officers. These are important operational roles but not primary decision-makers for enterprise sales execution, quoting, or field service platforms. Limited C-suite presence. Supply chain leaders attend but secondary vs. safety-focused buyers.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8bbe791d-724f-5634-b466-ebdaf40e8ac5', 'industry_alignment', 8, null, 'Restaurant supply chain vertical is highly aligned with InstaLILY ICP. Foodservice distributors and restaurant operators represent core buyer segments. Supply chain professionals and logistics management are directly impacted by quoting, order entry, and multi-location operational challenges that InstaLILY solves. Strong intersection with Parts Town (commercial restaurant equipment distributor) customer profile.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8bbe791d-724f-5634-b466-ebdaf40e8ac5', 'scale_timing', 7, null, 'Focused, invitation-only conference in May 2026, Chicago (accessible to US team). Exclusive format ensures quality of attendee pool but limits total event size. Timing is strategic and accessible. Restricted attendee eligibility (restaurant operators and supply chain professionals only) means fewer tire-kickers but tighter qualification funnel.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('8bbe791d-724f-5634-b466-ebdaf40e8ac5', 'buyer_quality', 7, null, 'Supply chain directors, procurement managers, logistics directors, and operations executives from restaurant and hospitality companies attending. These are decision-makers with direct budget authority for supply chain technology. Mix is heavily weighted toward operations and procurement leadership. C-suite presence likely present but secondary to operational executives.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('039b5502-ac89-5336-85e4-7a8cbcb70e6e', 'industry_alignment', 9, null, 'Restaurant and foodservice distribution is core InstaLILY vertical. Event attracts foodservice distributors, restaurant operators, and hospitality leaders—all direct buyers of AI Teammates for quoting and order management. Parts Town USA (major customer) operates in this vertical. 2,000+ exhibitors and 900+ product categories indicate deep industry engagement and buying committee representation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('039b5502-ac89-5336-85e4-7a8cbcb70e6e', 'scale_timing', 8, null, 'Western Hemisphere''s largest foodservice gathering, May 2026, Chicago (premier US location). Major annual event with 2,000+ exhibitors provides unmatched scale and prestige. Timing is mid-year which aligns with budget planning cycles. McCormick Place is accessible and high-traffic venue. Free expo pass lowers entry barrier for lead capture.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('039b5502-ac89-5336-85e4-7a8cbcb70e6e', 'buyer_quality', 8, null, 'Mix includes restaurant owners, foodservice distributors, chain executives, and hospitality leaders. Event attracts operators at multiple levels of sophistication and scale. Dealer/distributor presence indicates procurement and operations decision-makers. Chain executives and distributors attending represent high-authority buyers. Some attendees primary for exploration vs. active buying, but concentration of decision-makers is strong.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1f01fc75-6844-5260-ad13-99bb5c2728da', 'industry_alignment', 7, null, 'Automotive aftermarket and performance parts distribution aligns with InstaLILY automotive goods distributor ICP. Performance parts distributors, aftermarket retailers, and racing teams represent buyers in high-variation, high-SKU environment. However, this is niche aftermarket segment vs. broader automotive/industrial distribution. Less relevant than OEM supplier and heavy-duty truck parts distribution.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1f01fc75-6844-5260-ad13-99bb5c2728da', 'scale_timing', 6, null, 'New event in June 2026, Charlotte NC. Emerging conference focused on high-performance segment. Timing is acceptable and location is US-based. However, brand-new event format presents uncertainty about attendee quality, scale, and decision-maker concentration. Unproven track record vs. established conferences.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('1f01fc75-6844-5260-ad13-99bb5c2728da', 'buyer_quality', 6, null, 'Performance parts distributors and aftermarket retailers attending represent operations and procurement decision-makers. However, event emphasis on innovation showcase and content creation may attract enthusiasts and technical buyers vs. C-suite. Mix includes automotive shop owners and racing teams which are lower-authority buyers. Seniority distribution likely skews toward mid-level rather than executive.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('2dd86bf7-c514-5521-a6c9-c6a5a73b6b79', 'industry_alignment', 7, null, 'Grocery and convenience store distribution is food supply vertical aligned with InstaLILY ICP. Event serves wholesale distributors (McLane Company), retail buyers, and distribution managers. However, geographic scope is limited to Tennessee and Southeast region, reducing scope vs. national events. Attendee base skews toward retail operators vs. large multi-location distributors.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('2dd86bf7-c514-5521-a6c9-c6a5a73b6b79', 'scale_timing', 5, null, 'Regional event in June 2026, Chattanooga TN. Established annual event but smaller scale vs. national conferences. Chattanooga location is accessible to US Southeast team but less convenient than major hub cities. Free trade attendance lowers cost but suggests smaller event footprint. Timing is mid-year, acceptable for sales engagement.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('2dd86bf7-c514-5521-a6c9-c6a5a73b6b79', 'buyer_quality', 4, null, 'Grocery store owners, convenience store operators, and retail buyers attending. Distribution managers and category managers present but retail buyer focus suggests audience is small-to-medium independent/chain operators vs. enterprise-scale distributors. Seniority distribution likely skews toward store-level and local buying committee vs. corporate procurement authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('91e37f64-6a6c-5db4-a8a7-4dfe8dc3abd0', 'industry_alignment', 5, null, 'Construction supply vertical aligns with InstaLILY ICP (construction supply distributors like SRS Distribution). However, AIA Conference targets architects and design professionals, not construction supply distributors or building material suppliers. Exhibitors include building product manufacturers and construction tech, but audience functional focus is design and architecture, not procurement, operations, or distribution.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('91e37f64-6a6c-5db4-a8a7-4dfe8dc3abd0', 'scale_timing', 6, null, 'Major annual architecture conference in June 2026, San Diego (accessible US location). 600+ exhibitors and national scope. Established event with strong industry prestige. Timing and scale are strong. However, audience is architects and designers, not construction supply procurement or operations.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('91e37f64-6a6c-5db4-a8a7-4dfe8dc3abd0', 'buyer_quality', 1, null, 'Attendees are architects, interior designers, design-tech teams, and AEC professionals. Decision-makers for building product specifications and procurement authority reside with facility owners and construction managers, not primarily with architects. Limited concentration of procurement executives, supply chain directors, or operations leaders from construction distributors. Wrong buyer persona entirely.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('17086f3b-6455-569c-9fbb-d91adda1b0c6', 'industry_alignment', 9, null, 'Foodservice distribution is proven InstaLILY vertical (Parts Town USA operates in this space). Event purpose-built for operations professionals in food distribution—exact buyer functional alignment. Attendee focus on warehouse automation, inventory management, and fleet management directly aligns with InstaLILY value proposition (automating high-volume, multi-step operational workflows). Foodservice distributors are primary target.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('17086f3b-6455-569c-9fbb-d91adda1b0c6', 'scale_timing', 8, null, 'IFDA Operations Executive Conference in September 2026, San Antonio TX. Well-established IFDA event specifically designed for operations professionals. Major foodservice industry association backing ensures quality attendee pool. September timing aligns with Q4 budget planning and year-end operational initiatives. US-based location accessible to sales team.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('17086f3b-6455-569c-9fbb-d91adda1b0c6', 'buyer_quality', 9, null, 'Operations executives, warehouse managers, logistics directors, distribution center managers, and supply chain leaders attending. These are senior operational decision-makers with direct budget authority for automation and efficiency initiatives. High concentration of C-suite operations and logistics executives. IFDA membership and operations focus ensure attendee seniority and buying authority. Peer-to-peer networking format indicates active solution-seeking.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('87e8a8b8-f886-55d2-aed3-ff5698965cff', 'buyer_functional_alignment', 2, null, 'Audience is primarily engineers, designers, researchers, and technical professionals evaluating additive manufacturing technology. Very few attendees are in sales or operations decision-making roles typical of InstaLILY ICP. Focus is on manufacturing process technology, not distribution or sales operations automation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('87e8a8b8-f886-55d2-aed3-ff5698965cff', 'event_scale_timing', 9, null, 'Major established annual event with 10,000+ expected attendees. April 2026 timing is ideal and within optimal window. US-based in Boston with excellent accessibility. Four-day format with significant exhibit presence makes it easily accessible to sales team.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('87e8a8b8-f886-55d2-aed3-ff5698965cff', 'buyer_seniority', 2, null, 'While some senior executives and decision-makers attend, the majority composition skews toward engineers, project managers, and technical professionals rather than sales or operations executives with P&L responsibility. Limited concentration of C-suite or VP-level buyer personas.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('54a948d9-4307-52f7-93bc-b01ed698c531', 'buyer_functional_alignment', 10, null, 'Electrical distributors are core InstaLILY ICP. Audience is explicitly senior-level executives, national account managers, CEOs, presidents, and high-level decision-makers from electrical distributors. These are exactly the buyer personas InstaLILY targets - sales leadership and executive management at multi-location distribution companies.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('54a948d9-4307-52f7-93bc-b01ed698c531', 'event_scale_timing', 9, null, 'May 2026 timing is ideal for planning and budget cycles. Established annual conference for $70+ billion electrical distribution industry. Likely 2,000+ attendees based on sector size and NAED membership (5,100+ locations). Orlando location accessible to US sales team. Proven industry standard event.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('54a948d9-4307-52f7-93bc-b01ed698c531', 'buyer_seniority', 8, null, 'High concentration of C-suite and senior executives indicated by description emphasizing CEOs, presidents, and senior-level decision-makers. National account executives have budget authority for operational technology. Strong presence of buyers with decision-making power for large technology investments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ab7abafa-e5d3-5ecb-8c50-23ffe692d951', 'buyer_functional_alignment', 8, null, 'Electrical distribution industry is core vertical. Audience includes women professionals at all levels from entry to upper management in sales, operations, and management roles. Sales professionals and operations managers present represent relevant buyer functions, though attendee composition skews more toward development/networking vs. active solution-seeking.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ab7abafa-e5d3-5ecb-8c50-23ffe692d951', 'event_scale_timing', 6, null, 'June 2026 timing acceptable but later in planning cycle. Smaller niche event (women-focused subset of NAED community) vs. main NAED National Meeting. While vertical-relevant, attendance likely 500-1,000 vs. 2,000+ for main conference. Houston location accessible but requires targeted effort.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ab7abafa-e5d3-5ecb-8c50-23ffe692d951', 'buyer_seniority', 4, null, 'Attendees range from entry to upper management, but event design emphasizes career advancement and leadership development rather than product/solution evaluation. Upper management present but overall composition includes more mid-level and early-career professionals. Lower concentration of C-suite and P&L decision-makers vs. main NAED meeting.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('f85bee4f-3557-5d56-b1bf-227f222bdb37', 'supply_chain_vertical_alignment', 7, null, 'Field service operations are adjacent to InstaLILY ICP. While not direct 3PL or traditional distribution, field service companies managing technician workforces operate similar multi-location, high-volume operational models. Manufacturing, HVAC, and industrial equipment sectors mentioned overlap with InstaLILY verticals. However, event does not focus on traditional wholesale distribution or parts supply chains.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('f85bee4f-3557-5d56-b1bf-227f222bdb37', 'buyer_functional_alignment', 9, null, 'Audience is explicitly service directors, VP of services, field service managers, operations executives - all high-alignment with InstaLILY buyer personas. These roles manage complex workflows, technician utilization, work assignment, and operational efficiency. Perfect functional alignment for InstaLILY value proposition around execution and workflow automation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('f85bee4f-3557-5d56-b1bf-227f222bdb37', 'event_scale_timing', 8, null, 'April 2026 timing ideal for planning cycle. Established 20-year conference with 500+ senior service executives. San Diego Convention Center accessible venue. Three-day format focused on operational transformation. Proven event with strong industry adoption and attendance.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('f85bee4f-3557-5d56-b1bf-227f222bdb37', 'buyer_seniority', 8, null, 'High concentration of VPs, directors, and senior operations executives. Description indicates 60% service and support executive attendance rate. These are decision-makers with P&L responsibility and budget authority for digital transformation and workflow automation solutions.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5d473a1f-2972-5e10-b5cc-fb5c176014af', 'buyer_functional_alignment', 4, null, 'Fleet management is distinct function from sales and operations. Fleet managers, directors of fleet operations, and transportation managers focus on vehicle acquisition, maintenance, fuel, and logistics optimization. While they manage operations, they are not in sales or distribution contexts that drive InstaLILY use cases. Procurement specialists present but not aligned with InstaLILY quoting, sales velocity, or parts knowledge problems.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5d473a1f-2972-5e10-b5cc-fb5c176014af', 'event_scale_timing', 7, null, 'April 2026 timing ideal. Established annual event with 2,100+ fleet professionals. Cleveland venue accessible. Three-day format with 60+ sessions indicates substantial educational content. Proven industry standard with 60+ years of operation.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('5d473a1f-2972-5e10-b5cc-fb5c176014af', 'buyer_seniority', 6, null, 'Directors and managers of fleet operations have decision-making authority but focus is fleet procurement and operations, not technology platform adoption for sales/operations workflows. Some sustainability officers and procurement specialists present. Mid-level management present but not concentrated in roles aligned with InstaLILY buying authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('855daaee-72da-5147-bf5b-ff35da0fffe3', 'supply_chain_vertical_alignment', 10, null, 'TIA Capital Ideas Conference explicitly targets third-party logistics providers and freight brokers - exactly the asset-light 3PL and brokerage 3PL segment identified in Criteria Set B as highest-value supply chain vertical. Transportation intermediaries managing logistics operations and dispatch represent core supply chain audience alignment.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('855daaee-72da-5147-bf5b-ff35da0fffe3', 'buyer_functional_alignment', 8, null, 'Freight brokers, 3PL owners, senior managers, operations managers, and sales leaders all present. These are sales and operations-focused functions aligned with InstaLILY buyer personas. Audience manages high-volume, multi-stakeholder workflows (load matching, carrier assignment, customer management) analogous to distribution sales operations.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('855daaee-72da-5147-bf5b-ff35da0fffe3', 'event_scale_timing', 7, null, 'April 2026 timing solid. 1,500+ attendees is substantial for vertical-specific event. Phoenix venue accessible. Four-day format with 5+ general sessions and 24+ education tracks indicates meaningful educational programming. TIA organization represents $343 billion industry, indicating established event credibility.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('855daaee-72da-5147-bf5b-ff35da0fffe3', 'buyer_seniority', 7, null, 'Attendees explicitly include owners and senior managers of logistics companies with buying authority. Most attendees described as owners and senior managers with decision power. Mix of operations managers and sales leaders present. Strong concentration of decision-makers vs. junior staff.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('3d7b1127-2bc3-5e02-bf13-4c12ba28dbbb', 'supply_chain_vertical_alignment', 3, null, 'Event focuses on manufacturing operations, Lean/CI/OpEx, and continuous improvement rather than distribution, 3PL, brokerage, or procurement functions. Attendees from Toyota, Nestl, Intel, Tesla represent large manufacturers, not distributors or suppliers aligned with InstaLILY ICP. Manufacturing plants are not primary distribution/field service targets.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('3d7b1127-2bc3-5e02-bf13-4c12ba28dbbb', 'buyer_functional_alignment', 7, null, 'Strong executive presence with SVPs, VPs, and Directors of Manufacturing, Supply Chain, and Operations. These are decision-makers with budget authority. However, manufacturing plant operations differ from distribution sales/operations execution that InstaLILY targets.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('3d7b1127-2bc3-5e02-bf13-4c12ba28dbbb', 'event_scale_timing', 8, null, 'Single-day premier event in April 2026, US-based (Houston) and easily accessible to sales team. Established Executive Platforms franchise. 400+ attendees from 200+ organizations indicates solid scale and credibility.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('3d7b1127-2bc3-5e02-bf13-4c12ba28dbbb', 'buyer_seniority', 9, null, '91% of attendees at Director level and above with C-suite representation. High concentration of SVPs and VPs from Fortune 500 manufacturing companies. Strong decision-maker seniority across the board.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('62706723-49c7-5940-a6ab-2692189ec3b8', 'buyer_functional_alignment', 9, null, 'Strong alignment with InstaLILY target functions. Audience explicitly includes distributors, purchasers, and wholesalers - core sales and procurement decision-makers. OEMs and design engineers also present but secondary to distribution buyer focus. 79% of attendees have final say or influence on purchasing decisions, indicating high buyer authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('62706723-49c7-5940-a6ab-2692189ec3b8', 'event_scale_timing', 8, null, 'Two-day event in May 2026, well-established trade show for fastener industry. Charlotte, NC location is US-accessible and convenient for sales team deployment. 2-day format is optimal for meaningful engagement and pre-booked meeting strategy.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('62706723-49c7-5940-a6ab-2692189ec3b8', 'buyer_seniority', 9, null, 'Attendee base skews toward decision-makers and procurement authority (79% with purchasing influence). While specific C-suite percentages not detailed, the purchasing influence metric and distributor/wholesaler focus indicates high-level buyer presence. Likely mix of directors, branch managers, and procurement VPs.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('726f0e6b-92b4-5f18-acd4-ccb9ea4956b0', 'buyer_functional_alignment', 6, null, 'Mixed functional alignment. Audience includes procurement managers, supply chain directors, and manufacturing executives who align with InstaLILY operations targets. However, R&D leaders, regulatory experts, quality professionals, and business development executives represent adjacent/supporting functions rather than core sales or operations execution roles. CDMO/CMO focus is manufacturing-centric rather than distribution or field service.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('726f0e6b-92b4-5f18-acd4-ccb9ea4956b0', 'event_scale_timing', 8, null, 'Major 3-day event in June 2026, Philadelphia location is US-accessible. Expected 2,735+ attendees indicates strong scale. Established CPHI brand with renamed/reimagined 2026 format. Well-timed within H1/early H2 sales cycles.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('726f0e6b-92b4-5f18-acd4-ccb9ea4956b0', 'buyer_seniority', 7, null, 'Attendee base includes manufacturing executives, procurement managers, and supply chain directors with decision-making authority. However, audience is more diverse across technical, regulatory, and R&D functions rather than concentrated in high-level executive procurement/operations roles. Mix of mid-level and senior attendees.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('19e09a4d-9f14-59b7-b56a-9ae37685e64c', 'supply_chain_vertical_alignment', 2, null, 'ChemE Show is focused on chemical engineering, process automation, and biotechnology manufacturing - not distribution, supply chain operations, or field service delivery. While pharma is in InstaLILY ICP, this event targets equipment providers, engineers, and manufacturing plant operations rather than distributors, suppliers, or field-service organizations. No alignment with InstaLILY vertical-specific distribution or supply-chain operating models.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('19e09a4d-9f14-59b7-b56a-9ae37685e64c', 'buyer_functional_alignment', 3, null, 'Audience is primarily chemical engineers, CTOs, plant managers, process engineers, and regulatory professionals - technical and manufacturing-focused roles. These are not sales, operations, or distribution functions that InstaLILY targets. Decision-makers here own manufacturing workflows, not the repetitive quoting, order entry, or inventory management workflows that AI Teammates automate.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('19e09a4d-9f14-59b7-b56a-9ae37685e64c', 'event_scale_timing', 6, null, 'New event launching in 2026 at major Houston venue (George R. Brown) suggests significant backing and potential for strong attendance. US-based and well-timed for 2026 calendar. However, brand new event means uncertain attendance quality, no historical data on buyer concentration, and potentially unproven draw for targeted buyer personas.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('19e09a4d-9f14-59b7-b56a-9ae37685e64c', 'buyer_seniority', 2, null, 'Heavy presence of technical specialists (chemical engineers, process engineers, QC leads, facility planners) rather than business decision-makers. CTOs and plant managers are senior but own manufacturing operations, not commercial distribution or sales operations where InstaLILY creates value. Limited executive presence for commercial technology purchasing.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('a75eeed2-8ae8-5b8e-a38d-8653391e6456', 'buyer_functional_alignment', 5, null, 'Diverse attendee base including C-suite executives, research directors, investors, scientists, business development leaders, and regulatory professionals. While some sales/BD functions present, primary focus is research, investment, and biotechnology advancement rather than sales execution or operations optimization. Investor and academic presence dilutes practical buyer concentration.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('a75eeed2-8ae8-5b8e-a38d-8653391e6456', 'event_scale_timing', 9, null, 'World''s largest biotech event with 16,000+ attendees from 65+ countries and 1,600+ exhibitors. June 2026 timing is US-accessible (San Diego). Established flagship event with proven scale, credibility, and networking value. Attendance numbers are exceptional and demonstrate major industry influence.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('a75eeed2-8ae8-5b8e-a38d-8653391e6456', 'buyer_seniority', 8, null, 'High concentration of C-suite executives, research directors, and investors. Large biotech companies and startups represented. Decision-maker seniority is strong. However, scientific researcher and investor presence limits operational buyer focus compared to manufacturing/distribution executives.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('88a537a3-94cb-5ac9-8774-ebe33c4cbb37', 'buyer_functional_alignment', 7, null, 'Strong executive presence in manufacturing, technical operations, quality, and supply chain optimization. SVPs, VPs, and Directors represent operations and quality decision-makers. However, audience focuses on pharmaceutical manufacturing operations and plant optimization rather than sales execution or multi-location field distribution/service operations InstaLILY targets.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('88a537a3-94cb-5ac9-8774-ebe33c4cbb37', 'event_scale_timing', 7, null, 'Three-day event in May 2026, Boston location is US-accessible and convenient. Approximately 200 attendees from global pharma organizations indicates solid but smaller-scale event compared to major trade shows. 30 exhibitors and 52 speakers suggest professional, curated summit format rather than massive trade show.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('88a537a3-94cb-5ac9-8774-ebe33c4cbb37', 'buyer_seniority', 9, null, 'Attendees primarily at Director level and above, including SVPs, VPs, and Technology Leaders from major pharmaceutical companies (Eli Lilly, Takeda, Bristol Myers Squibb, etc.). High concentration of C-suite and senior executive decision-makers with significant budget authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('7e50451b-0913-547b-b2f7-a1eaf4609b32', 'buyer_functional_alignment', 9, null, 'Strong alignment with InstaLILY ICP. Attendee mix includes fastener distributors, sourcing professionals, purchasers, and sales representatives - core buyer personas for AI-driven quoting and operations automation. OEMs and suppliers also present represent complementary buyer profiles. Heavy concentration on sales, procurement, and supply chain operations functions.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('7e50451b-0913-547b-b2f7-a1eaf4609b32', 'event_scale_timing', 8, null, 'North Americas largest fastener B2B trade show with 4,000-5,000 attendees from 30+ countries. October 2026 timing is ideal for budget planning cycles. US-based event in Phoenix (accessible to US sales team). Well-established, reputable annual event with strong industry presence and credibility.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('7e50451b-0913-547b-b2f7-a1eaf4609b32', 'buyer_seniority', 7, null, 'Mix of decision-maker levels present. Sourcing professionals, purchasers, and sales representatives indicate operational leaders with buying authority. OEM attendance suggests some C-suite/VP participation. Primarily mid to senior management rather than pure C-suite concentration, but sufficient seniority for solution discussions.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('22173552-a4c5-5b92-be82-8f992c9e5bb1', 'buyer_functional_alignment', 2, null, 'Attendee base is primarily power systems engineers, grid operators, electrical engineers, and utility operations teams. While operations-focused, these are infrastructure/engineering operations roles, not commercial distribution or sales operations that drive InstaLILY value. No sales enablement, quoting, order management, or field service execution functions represented. Audience skews heavily technical and regulatory rather than business operations.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('22173552-a4c5-5b92-be82-8f992c9e5bb1', 'event_scale_timing', 3, null, 'Event is large and well-established (15,000+ attendees, 900+ exhibitors, biennial major conference) occurring in May 2026 within proper timeframe. However, geography and format are challenging for InstaLILY sales team resource allocation. Highly technical, engineering-focused conference format makes traditional enterprise sales outreach difficult.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('22173552-a4c5-5b92-be82-8f992c9e5bb1', 'buyer_seniority', 2, null, 'Mix includes utility executives and decision-makers, but majority of attendees are engineers, technicians, system planners, and operational staff rather than C-suite or VP-level buyers with budget authority for enterprise software platforms. Decision-makers present are focused on infrastructure and grid modernization, not business process automation or sales/operations technology.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('9af99713-c3c7-5412-b180-dc000349b0d4', 'buyer_functional_alignment', 3, null, 'While the event attracts senior retail executives and supply chain managers, the primary audience is retail merchants, digital commerce leaders, and merchandising teams. InstaLILY targets distributors, suppliers, and field-service operations - not retail end-buyers. Supply chain managers present are typically focused on inbound fulfillment and retail logistics rather than B2B distribution operations, quoting systems, or parts catalogs that drive InstaLILY value.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('9af99713-c3c7-5412-b180-dc000349b0d4', 'event_scale_timing', 9, null, 'Major annual US event in January 2026 with 40,000+ attendees, established 30+ year reputation, and premium venue (Javits Center NYC). Easily accessible to US sales team and represents one of retail industrys largest gatherings. Timing is optimal for Q1 2026 outreach campaigns.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('9af99713-c3c7-5412-b180-dc000349b0d4', 'buyer_seniority', 8, null, 'High concentration of C-suite executives (CEOs, Chief Digital Officers, VP Supply Chain) with significant budget authority attending. Strong presence of senior decision-makers from major national and international retailers. Speaker lineup likely includes retail industry leaders with enterprise purchasing power.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ba47136e-eaa9-56b1-b242-41fb37906036', 'supply_chain_vertical_alignment', 4, null, 'Event targets manufacturers and distributors broadly, which includes InstaLILY ICP verticals. However, the primary focus is eCommerce, digital marketing, and customer experience transformation rather than operational execution, workflow automation, or supply chain execution. While distributors attend, the conference is not designed for supply chain operations, procurement optimization, or field service execution - the core use cases where InstaLILY drives measurable ROI. Vertical alignment exists but is indirect.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ba47136e-eaa9-56b1-b242-41fb37906036', 'buyer_functional_alignment', 6, null, 'Attendee mix heavily skews toward marketing and digital commerce functions - CMOs, VPs of eCommerce, Digital Marketing Directors. While some operational roles present (IT Directors, Digital Transformation officers), the event is primarily designed for customer-facing digital strategy rather than back-office operations, sales execution, or field service management where InstaLILY creates impact. Functional mismatch with InstaLILY buyer personas who need workflow automation and operational AI.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ba47136e-eaa9-56b1-b242-41fb37906036', 'event_scale_timing', 8, null, 'Established annual B2B conference in major US city (Atlanta) with 300-600+ expected attendees. November 2026 timing is within target window and accessible to US sales team. Three-day format allows meaningful engagement. Solid event scale and logistics, though not mega-conference tier.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('ba47136e-eaa9-56b1-b242-41fb37906036', 'buyer_seniority', 7, null, 'Strong concentration of senior executives - CMOs, VPs, Directors from enterprise and mid-market organizations. Clear presence of decision-makers with budget authority for digital transformation initiatives. However, seniority is concentrated in marketing and eCommerce leadership rather than operations, supply chain, or sales execution leadership where InstaLILY deals close.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('531982f6-22cc-5325-b04d-d61bcc9046d1', 'supply_chain_vertical_alignment', 5, null, 'Event targets B2B eCommerce and digital transformation in manufacturers and distributors, which touches supply chain but is not core to InstaLILY vertical alignment. Focus is on eCommerce platforms, PIM solutions, and digital consultancies rather than the execution-focused operational workflows (quoting, parts validation, triage) that InstaLILY solves. Not aligned with asset-light 3PLs, freight forwarding, LTLs, or procurement verticals that drive highest value for supply chain focus.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('531982f6-22cc-5325-b04d-d61bcc9046d1', 'buyer_functional_alignment', 8, null, 'Strong alignment with executive decision-makers. Attendees include VP/Director eCommerce, Chief Digital Officers, VP Digital Marketing, VP Customer Experience, and leaders owning omnichannel strategy and digital transformation. These are high-authority buyers involved in technology investment decisions. Some operations and sales leadership likely present, though primary focus leans toward digital/marketing functions rather than core sales or operations execution.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('531982f6-22cc-5325-b04d-d61bcc9046d1', 'event_scale_timing', 7, null, '3-day event in June 2026 at established resort venue. US-based and accessible to sales team. Smaller, more intimate format (invite-only, curated peer discussions) vs. large trade shows, but strong positioning as senior-level executive retreat. Established event by WBR Research with credible attendee base. Timing in June is acceptable though not peak buying season.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('531982f6-22cc-5325-b04d-d61bcc9046d1', 'buyer_seniority', 8, null, 'High concentration of C-suite and VP-level executives. Invite-only format ensures attendee quality and decision-maker presence. Named companies (J.J. Keller, Sunbelt Rentals, Sensata) represent mid-market to enterprise organizations with budget authority. Format explicitly designed for peer discussions and 1:1 meetings with vendors, indicating serious buyer intent and seniority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('557a849b-dc84-5ba8-9948-6611af023b21', 'supply_chain_vertical_alignment', 3, null, 'Event focuses heavily on last-mile delivery, e-commerce fulfillment, and retail logistics optimization. This is asset-light 3PL, freight forwarding, and logistics technology space - not core InstaLILY verticals. While supply chain adjacent, the event does not serve InstaLILY target industries: construction supply, industrial parts, healthcare/pharma, automotive goods, or food supply distributors. E-commerce fulfillment and last-mile delivery represent different operational models than multi-branch distributors and field service operations InstaLILY targets.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('557a849b-dc84-5ba8-9948-6611af023b21', 'buyer_functional_alignment', 6, null, 'Audience includes logistics managers, supply chain directors, and distribution center operators - roles adjacent to InstaLILY target functions. However, buyer mix skews toward e-commerce retailers (Target, Walfair, Kroger) and 3PLs rather than B2B distributors and field service operations. These attendees prioritize fulfillment velocity and last-mile execution rather than sales enablement, quoting, or field technician workflows that InstaLILY solves.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('557a849b-dc84-5ba8-9948-6611af023b21', 'event_scale_timing', 7, null, 'Major annual US event in 2026 with 2,000-5,000 attendees, 250+ speakers, and strong industry reputation (Platinum tier). Nashville location accessible to US sales team. May timing works within planning calendar. However, e-commerce/retail logistics focus means attendee quality for InstaLILY targeting is diluted despite overall event scale.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('557a849b-dc84-5ba8-9948-6611af023b21', 'buyer_seniority', 4, null, 'Mix of logistics managers, supply chain directors, and some C-suite retail/manufacturer leaders. However, the predominant attendee base skews toward logistics operations and technology roles rather than executive decision-makers at distributor or field service organizations. Lower concentration of sales leadership, procurement executives, or operations VPs at B2B distributors compared to pure supply chain/logistics roles.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fc21a7b8-f2a2-599c-adf1-dd08f2bf138c', 'supply_chain_vertical_alignment', 2, null, 'Broker-carrier summit focuses on freight brokerage and trucking carrier operations - asset-light 3PLs and logistics service providers. This vertical is fundamentally misaligned with InstaLILY ICP. InstaLILY targets distributors, manufacturers, and field-service operations that manage complex inventory, parts catalogs, and multi-branch sales operations. Freight brokerage is a pure logistics/transportation play with no product distribution, parts management, or field-service execution components. Wrong supply chain vertical entirely.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fc21a7b8-f2a2-599c-adf1-dd08f2bf138c', 'buyer_functional_alignment', 5, null, 'Attendees are freight brokers, trucking carriers, 3PLs, and transportation logistics professionals. While some attendees hold operational roles, the dominant functions are logistics coordination, carrier relationship management, and load optimization - not sales operations, order management, or parts fulfillment that InstaLILY targets. Some supporting functions tangentially related to operations exist, but core buyer personas lack alignment with InstaLILY use cases.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fc21a7b8-f2a2-599c-adf1-dd08f2bf138c', 'event_scale_timing', 7, null, 'Well-established semiannual event with April 2026 dates falling squarely within target window. US-based in Kansas City metro (Overland Park, KS) making it geographically accessible to sales team. Moderate attendance event with strong industry reputation (though branded as 3 days despite being 2-day format). Represents meaningful industry gathering, though smaller than mega-conferences.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('fc21a7b8-f2a2-599c-adf1-dd08f2bf138c', 'buyer_seniority', 3, null, 'Attendee base skews toward operational practitioners - fleet owners, logistics coordinators, and carrier partnership managers - rather than C-suite decision-makers. Technology decision-makers present but likely focused on TMS and carrier verification tools rather than broader operational AI. Limited evidence of VP/C-level concentration typical of enterprise software buying committees. Attendee profile suggests transaction-oriented rather than strategic purchasing authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('7a60b4d4-9939-5cb9-9f22-c14fe229b061', 'event_validity', 0, null, 'Event cannot be scored due to insufficient data. Enrichment failed to confirm event existence, dates, location, or attendee profile. The domain analyticon.ai does not host an active, publicly accessible conference. Historical references to Analyticon show either internal/private events (Amazon analytics conference) or discontinued conferences (United Scientific Group chemistry events last held in 2022). No 2026 event dates could be verified.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('6d4e9291-21d4-5ca3-9f92-020b6dd51470', 'supply_chain_vertical_alignment', 4, null, 'Event targets broad supply chain professionals across multiple verticals including manufacturing, retail, and logistics. While it includes some 3PLs and logistics operators, the audience mix is too generalized and skews toward European logistics infrastructure providers rather than InstaLILY target verticals of distributors, manufacturers, and field service operations in construction, industrial parts, healthcare, automotive, or food supply.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('6d4e9291-21d4-5ca3-9f92-020b6dd51470', 'buyer_functional_alignment', 8, null, 'Strong concentration of C-level executives, operations directors, and procurement heads with direct budgetary authority. These are decision-making roles aligned with InstaLILY buyer personas. However, the functional mix is broader than ideal, including general supply chain visibility seekers rather than execution-focused operations buyers.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('6d4e9291-21d4-5ca3-9f92-020b6dd51470', 'event_scale_timing', 3, null, 'Event is in 2026 which passes timing check, but location is London, UK with limited accessibility for US sales team. Small event format (60+ attendees) is significantly below InstaLILY investment threshold. International logistics-focused audience reduces relevance for US-centric distributor and manufacturer ICP.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('6d4e9291-21d4-5ca3-9f92-020b6dd51470', 'buyer_seniority', 8, null, 'Explicitly targets C and D-level executives with direct budgetary authority. Free attendance model attracts serious decision-makers. Curated one-to-one meeting format indicates high-intent, senior buyer participation. Strong concentration of purchase authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c8c6dcd3-309c-5770-bfa7-199547c1a30f', 'supply_chain_vertical_alignment', 5, null, 'Event targets retail and e-commerce supply chain leaders with focus on last-mile delivery, fulfillment, and returns management. While this includes some logistics technology and warehouse automation vendors, the overwhelming attendee concentration is retail and e-commerce operations. This vertical misalignment is significant - InstaLILY target distributors, manufacturers, and field service in construction, industrial, healthcare, automotive, and food. Retail fulfillment operations are outside core ICP.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c8c6dcd3-309c-5770-bfa7-199547c1a30f', 'buyer_functional_alignment', 9, null, 'Excellent functional alignment with retail executives, e-commerce operations leaders, supply chain directors, and logistics decision-makers. C and D-level focus ensures high-intent, budget-holding attendees. These are exactly the operational and supply chain executive roles that drive buying decisions.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c8c6dcd3-309c-5770-bfa7-199547c1a30f', 'event_scale_timing', 2, null, 'Event is in 2026 which passes date check, but location is Amsterdam, Netherlands. US sales team accessibility is problematic for European event. While attendance scale is impressive (1,500 attendees), geographic location and associated travel costs make this a poor investment for US-centric sales strategy.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('c8c6dcd3-309c-5770-bfa7-199547c1a30f', 'buyer_seniority', 9, null, 'Exceptional concentration of C and D-level retail executives with high budgetary authority. Event model provides fully hosted VIP experience for qualified decision-makers, indicating serious, intent-driven participation. 1,000+ senior retail decision-makers represent highest-level buyer concentration. Strong purchase authority and solution-seeking mentality evident from format.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('018da698-3d23-5f98-9b32-7d423e6776a7', 'buyer_functional_alignment', 7, null, 'Event targets merchant professionals, supplier relationships, and business decision-makers in building, plumbing, heating, and hardware sectors. Functional mix includes independent merchants and supplier representatives. While these are operational and business leaders, the audience is less focused on high-volume, execution-oriented sales and operations than ideal InstaLILY buyers. More relationship-focused than transaction-process-focused.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('018da698-3d23-5f98-9b32-7d423e6776a7', 'event_scale_timing', 2, null, 'Event is in 2026 which passes date check, but location is Alicante, Spain creating significant accessibility barrier for US sales team. Scale is moderate (420 delegates at 2024 edition), well below InstaLILY target investment threshold. Biennial frequency means lower predictability and consistency for ongoing event strategy. International location and travel requirements reduce practical feasibility.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('018da698-3d23-5f98-9b32-7d423e6776a7', 'buyer_seniority', 6, null, 'Mix of independent merchant decision-makers and suppliers attending. While merchants likely hold purchase authority, the audience includes both buyers and sellers with mixed seniority levels. Not explicitly C-suite focused like premium events. Relationship-building focus suggests mid-level to senior merchant professionals rather than highest-level decision-making concentration.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('64d5a331-4f82-5525-a379-cfd92d069a38', 'supply_chain_vertical_alignment', 6, null, 'Event serves freight, logistics, and supply chain management with 300+ exhibitors across modal transportation (road, rail, sea, air) and warehousing. Strong presence of carriers, logistics providers, warehouse automation, and technology vendors. However, audience is heavily weighted toward logistics operators, freight forwarders, and 3PLs rather than InstaLILY target verticals of product distributors, manufacturers, and field service. Logistics infrastructure focus rather than distribution operations focus.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('64d5a331-4f82-5525-a379-cfd92d069a38', 'buyer_functional_alignment', 8, null, 'Excellent functional mix of supply chain professionals, logistics decision-makers, warehouse operators, and cargo owners with operational authority. These are operations and logistics management roles central to InstaLILY buyer personas. Large volume of shippers and manufacturers attendees increases relevance. However, significant portion of audience are carriers and logistics service providers outside core ICP.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('64d5a331-4f82-5525-a379-cfd92d069a38', 'event_scale_timing', 7, null, 'Established major event (19th year) in 2026 with 13,500+ industry professionals attending. Free attendance removes barrier. Located in Birmingham, UK - while not US-based, it is UK which has reasonable accessibility for US sales team travel compared to continental Europe. June-July timing is appropriate for sales cycle. Large scale and established reputation indicate quality event, but UK location reduces accessibility versus US events.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('64d5a331-4f82-5525-a379-cfd92d069a38', 'buyer_seniority', 6, null, 'Mix of senior supply chain professionals, decision-makers, and operators attending. Event features expert speakers and 80+ CPD-accredited conference sessions, attracting serious participants. However, attendee mix is broad across skill levels from junior logistics staff to senior decision-makers. Not explicitly C-suite focused. Logistics operator concentration suggests mid-level to senior management rather than highest executive authority.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('587717a6-dd08-5d95-a169-b36440cb66b7', 'buyer_functional_alignment', 9, null, 'Strong alignment with InstaLILY ICP buyer functions. Audience explicitly includes C-level executives, sales professionals, purchasing managers, and operations leaders. Performance plastics distributors are multi-location, inventory-intensive operations with high SKU complexity - core pain points InstaLILY solves. Sales and operations functions dominate attendee profile.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('587717a6-dd08-5d95-a169-b36440cb66b7', 'event_scale_timing', 8, null, 'Established 70th annual convention occurring September 28-October 1, 2026 within optimal timing window. Held in Atlanta, GA - easily accessible to US-based sales team. Four-day format with dedicated trade show (connecX) indicates mature, well-resourced event. Mid-sized niche event rather than mega-conference, which can actually improve targeting precision.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('587717a6-dd08-5d95-a169-b36440cb66b7', 'buyer_seniority', 8, null, 'Explicitly states high concentration of C-level executives alongside sales professionals, purchasing managers, and operations leaders. Four-day event structure with committee meetings and private supplier meetings suggests senior decision-maker participation. Not a junior-heavy event - attendees have budget authority for operational technology investments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('0786a625-4ad2-57a9-ade5-f2365b7a831d', 'buyer_functional_alignment', 4, null, 'Audience is heavily technical and engineering-focused: chemical engineers, process engineers, CTOs, plant managers, EPC firms. While plant managers and facility planners exist, primary attendee base is technical specialists and engineering decision-makers rather than sales, operations execution, or procurement functions InstaLILY targets.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('0786a625-4ad2-57a9-ade5-f2365b7a831d', 'event_scale_timing', 6, null, 'Brand-new event launching in 2026 (June 9-10, Houston). While Houston is US-accessible and June timing is convenient, inaugural event status means uncertain attendance, speaker quality, and industry impact. Partnership between Gulf Energy and DECHEMA provides credibility, but first-year events are inherently risky investments.');
insert into public.event_score_factors (event_id, factor_key, score, weight, rationale) values ('0786a625-4ad2-57a9-ade5-f2365b7a831d', 'buyer_seniority', 4, null, 'Audience includes CTOs, plant managers, biopharma executives, and facility planners suggesting some senior presence. However, emphasis on chemical engineers, process engineers, and regulatory professionals indicates significant technical/specialist representation rather than C-suite concentration.');

